package net.zartra.gui;
import java.util.*;
final class MenuPagination {private MenuPagination(){}static int pages(MenuDefinition menu){int slots=menu.paginationContentSlots.size();if(slots<=0)return 1;int dynamic=menu.items.size();return Math.max(1,(dynamic+slots-1)/slots);}static int page(MenuDefinition menu,int requested){return Math.max(1,Math.min(pages(menu),requested));}static List<MenuItem> dynamic(MenuDefinition menu){List<MenuItem> list=new ArrayList<MenuItem>();for(Map.Entry<Integer,MenuItem> e:menu.items.entrySet())list.add(e.getValue());Collections.sort(list,new Comparator<MenuItem>(){public int compare(MenuItem a,MenuItem b){return b.priority-a.priority;}});return list;}static Map<Integer,MenuItem> pageItems(MenuDefinition menu,int requested){Map<Integer,MenuItem> out=new HashMap<Integer,MenuItem>();if(menu.paginationContentSlots.isEmpty()){out.putAll(menu.items);return out;}List<MenuItem> all=dynamic(menu);int page=page(menu,requested),start=(page-1)*menu.paginationContentSlots.size();for(int n=0;n<menu.paginationContentSlots.size()&&start+n<all.size();n++)out.put(menu.paginationContentSlots.get(n),all.get(start+n));return out;}static boolean valid(MenuDefinition menu){return menu.validPaginationSlots();}}